using AdDatabase.BLL.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace AdDatabase.API.Controllers;[Authorize,ApiController,Route("api/uploads")]public class UploadsController(IWebHostEnvironment env):ControllerBase{static readonly HashSet<string> Allowed=[".jpg",".jpeg",".png",".webp"];[HttpPost("images"),RequestSizeLimit(10_000_000)]public async Task<IActionResult>Image(IFormFile file,CancellationToken ct){if(file.Length==0||file.Length>10_000_000)throw new InvalidOperationException("Invalid file size");var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(!Allowed.Contains(ext))throw new InvalidOperationException("Only JPG, PNG and WebP are accepted");var dir=Path.Combine(env.WebRootPath??Path.Combine(env.ContentRootPath,"wwwroot"),"uploads");Directory.CreateDirectory(dir);var name=$"{Guid.NewGuid():N}{ext}";await using var stream=System.IO.File.Create(Path.Combine(dir,name));await file.CopyToAsync(stream,ct);return Ok(ApiResponse<string>.Ok($"/uploads/{name}","Uploaded"));}}
